flowchart TB
  H1@{ svc: "AWS Health", label: "標準の各リージョン<br/>アカウント固有のイベント" }
  IAM@{ svc: "AWS IAM", label: "リージョンに属さないイベント" }
  R1@{ svc: "Amazon EventBridge", label: "米国西部（オレゴン）<br/>✔ A: 中央のルール 1 つ" }
  R2@{ svc: "Amazon EventBridge", label: "バージニア北部<br/>✔ B: グローバルなイベントのルール" }
  H1 == "✔ A: 全リージョンの分" ==> R1
  IAM == "✔ B" ==> R2
  CDE["⚠ C: 各リージョンにルール（数が増え IAM は受けられない）<br/>⚠ D: 簡素化された統合（公開イベントは対象外）<br/>⚠ E: 主なリージョンのルールだけ（他は集まらない）"]
  CDE -.-> R1
